        arrayOf("\"\ud83d\ude00 abcdefghijklmnopqrstuvwxyze", "Unterminated string in JSON at position 31 (line 1 column 32)"),
        arrayOf("\"\ud83d\ude00 abcdefghijklmnopqrstuvwxyz\" ", ""),
        arrayOf("\"\ud83d\ude00 abcdefghijklmnopqrstuvwxyz\":", "Unexpected non-whitespace character after JSON at position 31 (line 1 column 32)"),
        arrayOf("\"\ud83d\ude00 abcdefghijklmnopqrstuvwxyz\"u", "Unexpected non-whitespace character after JSON at position 31 (line 1 column 32)"),
    )

    @Test
    fun matchesJsonParse() {
        assertEquals(535, rows.size)
        for (r in rows) assertEquals(r[0], r[1], V8Json.error(r[0]))
    }
}
